from functools import cmp_to_key


def fractionalKnapsack(items, capacity):
    def cmp(x, y):
        # larger value/weight first
        return y[0] * x[1] - x[0] * y[1]

    order = sorted(items, key=cmp_to_key(lambda x, y: -(x[0] * y[1] - y[0] * x[1])))
    total = 0
    rem = capacity
    for v, w in order:
        if rem == 0:
            break
        if w <= rem:
            total += v
            rem -= w
        else:
            total += (v * rem) // w
            rem = 0
    return total
